window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-585152b9d4045ad7"]={"versions": [{"id": "FIG-585152b9d4045ad7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (AUTOSAR M2-Ebene, Package <code>M2::AUTOSARTemplates::AdaptivePlatform::General</code>).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Modellierung der physischen Speicher- bzw. Dateipfadlokation (<code>uri</code>) eines durch ein logisches Modellelement (z. B. <code>Executable</code>, Konfigurationsdatei) repräsentierten Software-Artefakts innerhalb eines <code>SoftwareCluster</code>. Es dient der statischen Bindung zwischen ARXML-Designmodell und den realen Binär-/Dateiartefakten im Deployment-, Packaging- und Update-Prozess (UCM – Update and Config Management) der AUTOSAR Adaptive Platform.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(abstrakt; Basisklassen: <code>MultilanguageReferrable</code>, <code>Referrable</code>, <code>ARObject</code>)</em>\n<ul class=\"fig-list\"><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ category: CategoryString [0..1]</code>: Klassifikation des Modellelements.\n</li><li><code>+ uuid: String [0..1]</code>: Universally Unique Identifier zur modellweiten Nachverfolgbarkeit.\n</li></ul>\n</li><li>Rolle: Dient als generischer Typ und Zielanker für Modellelemente, die durch physische Artefakte manifestiert werden.\n</li></ul>\n</li><li><strong><code>ArtifactLocator</code></strong> <em>(konkret)</em>\n<ul class=\"fig-list\"><li>Vererbung: Generalisiert von <code>Identifiable</code> (erbt <code>uuid</code>, <code>category</code> sowie Namens- und Referenzierungssemantik).\n</li><li>Aggregation: Wird im Gesamtmodell durch <code>SoftwareCluster.artifactLocator</code> aggregiert.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ uri: String [1]</code>: Eindeutiger URI-/Pfadbezeichner, der den physischen Speicherort des Artefakts angibt.\n</li></ul>\n</li><li>Ausgehende Assoziation:\n<ul class=\"fig-list\"><li><code>+representedModelElement: Identifiable [0..1]</code>: Unidirektionale Referenz auf das logische Modellelement, dessen Artefaktlokation bestimmt wird.\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Metamodell:</strong> Kein direkter dynamischer Kontrollfluss auf C++-API-Ebene.\n</li><li><strong>Lebenszyklus- &amp; Bindungsphasen:</strong>\n<ol class=\"fig-list\"><li><em>Manifest-Generierung:</em> Werkzeuge ordnen erzeugte Binärdateien/Bibliotheken den Modellelementen über <code>ArtifactLocator</code> zu.\n</li><li><em>Manifest-Finalisierung:</em> Validierungszeitpunkt von Konsistenzbedingungen (insbes. Kardinalitätsprüfungen).\n</li><li><em>UCM-Installation / Execution Management:</em> Beim Einspielen eines Software-Pakets liest der Update and Config Manager den <code>uri</code> aus, extrahiert das Artefakt an den definierten Dateisystempfad und das Execution Management instanziiert bzw. startet die adressierte Binärdatei basierend auf der Verknüpfung zu <code>Executable</code>.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Strikte 1:1-Restriktion (<code>[constr_10380]{DRAFT}</code>):</strong> \n<ul class=\"fig-list\"><li>Ein Modellelement (<code>Identifiable</code>), das Ziel einer Referenz in der Rolle <code>ArtifactLocator.representedModelElement</code> ist, darf in keinem anderen <code>ArtifactLocator</code> als Ziel referenziert werden.\n</li><li>Diese Regel wird zum Zeitpunkt der Manifest-Finalisierung (<code>Manifest Creation Finished</code>) verbindlich forciert. Ein Modell, das versucht, demselben Modellelement mehrere unterschiedliche Lokationen zuzuordnen, ist ungültig.\n</li></ul>\n</li><li><strong>Entwickler- &amp; Tooling-Auswirkungen:</strong>\n<ul class=\"fig-list\"><li><em>Generatoren/Build-Pipelines:</em> Müssen sicherstellen, dass pro Modellentität (z. B. Executable eines Adaptive Application Prozesses) genau eine physische Datei per relativem oder absolutem URI hinterlegt ist.\n</li><li><em>Packaging:</em> Der im Attribut <code>uri</code> hinterlegte Pfad muss relativ zur Verzeichnisstruktur des Software-Cluster-Containers konsistent und deterministisch auflösbar sein.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4a9621efde340c5b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (AUTOSAR M2-Ebene, Package <code>M2::AUTOSARTemplates::AdaptivePlatform::General</code>).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Modellierung der physischen Speicher- bzw. Dateipfadlokation (<code>uri</code>) eines durch ein logisches Modellelement (z. B. <code>Executable</code>, Konfigurationsdatei) repräsentierten Software-Artefakts innerhalb eines <code>SoftwareCluster</code>. Es dient der statischen Bindung zwischen ARXML-Designmodell und den realen Binär-/Dateiartefakten im Deployment-, Packaging- und Update-Prozess (UCM – Update and Config Management) der AUTOSAR Adaptive Platform.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Identifiable</code></strong> <em>(abstrakt; Basisklassen: <code>MultilanguageReferrable</code>, <code>Referrable</code>, <code>ARObject</code>)</em>\n<ul class=\"fig-list\"><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ category: CategoryString [0..1]</code>: Klassifikation des Modellelements.\n</li><li><code>+ uuid: String [0..1]</code>: Universally Unique Identifier zur modellweiten Nachverfolgbarkeit.\n</li></ul>\n</li><li>Rolle: Dient als generischer Typ und Zielanker für Modellelemente, die durch physische Artefakte manifestiert werden.\n</li></ul>\n</li><li><strong><code>ArtifactLocator</code></strong> <em>(konkret)</em>\n<ul class=\"fig-list\"><li>Vererbung: Generalisiert von <code>Identifiable</code> (erbt <code>uuid</code>, <code>category</code> sowie Namens- und Referenzierungssemantik).\n</li><li>Aggregation: Wird im Gesamtmodell durch <code>SoftwareCluster.artifactLocator</code> aggregiert.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ uri: String [0..1]</code>: Eindeutiger URI-/Pfadbezeichner, der den physischen Speicherort des Artefakts angibt.\n</li></ul>\n</li><li>Ausgehende Assoziation:\n<ul class=\"fig-list\"><li><code>+representedModelElement: Identifiable [0..1]</code>: Unidirektionale Referenz auf das logische Modellelement, dessen Artefaktlokation bestimmt wird.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Metamodell:</strong> Kein direkter dynamischer Kontrollfluss auf C++-API-Ebene.\n</li><li><strong>Lebenszyklus- &amp; Bindungsphasen:</strong>\n<ol class=\"fig-list\"><li><em>Manifest-Generierung:</em> Werkzeuge ordnen erzeugte Binärdateien/Bibliotheken den Modellelementen über <code>ArtifactLocator</code> zu.\n</li><li><em>Manifest-Finalisierung:</em> Validierungszeitpunkt von Konsistenzbedingungen (insbes. Kardinalitätsprüfungen).\n</li><li><em>UCM-Installation / Execution Management:</em> Beim Einspielen eines Software-Pakets liest der Update and Config Manager den <code>uri</code> aus, extrahiert das Artefakt an den definierten Dateisystempfad und das Execution Management instanziiert bzw. startet die adressierte Binärdatei basierend auf der Verknüpfung zu <code>Executable</code>.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Strikte 1:1-Restriktion (<code>[constr_10380]{DRAFT}</code>):</strong> \n<ul class=\"fig-list\"><li>Ein Modellelement (<code>Identifiable</code>), das Ziel einer Referenz in der Rolle <code>ArtifactLocator.representedModelElement</code> ist, darf in keinem anderen <code>ArtifactLocator</code> als Ziel referenziert werden.\n</li><li>Diese Regel wird zum Zeitpunkt der Manifest-Finalisierung (<code>Manifest Creation Finished</code>) verbindlich forciert. Ein Modell, das versucht, demselben Modellelement mehrere unterschiedliche Lokationen zuzuordnen, ist ungültig.\n</li></ul>\n</li><li><strong>Entwickler- &amp; Tooling-Auswirkungen:</strong>\n<ul class=\"fig-list\"><li><em>Generatoren/Build-Pipelines:</em> Müssen sicherstellen, dass pro Modellentität (z. B. Executable eines Adaptive Application Prozesses) genau eine physische Datei per relativem oder absolutem URI hinterlegt ist.\n</li><li><em>Packaging:</em> Der im Attribut <code>uri</code> hinterlegte Pfad muss relativ zur Verzeichnisstruktur des Software-Cluster-Containers konsistent und deterministisch auflösbar sein.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-585152b9d4045ad7", "to": "FIG-4a9621efde340c5b", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ArtifactLocator</code>: Multiplizität des Attributs <code>+ uri</code> von <code>String</code> (obligatorisch, [1]) auf <code>String [0..1]</code> (optional) geändert.\n</li></ul>"}]};
